const config = {
  "previewFeatures": [],
  "clientVersion": "7.7.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// Required for creating a User: id, name, email, image, cart (optional JSON array of cart items)\nmodel User {\n  id        String   @id\n  name      String\n  email     String\n  image     String\n  cart      Json     @default(\"[]\") // array of { productId, quantity, variants? }\n  isBanned  Boolean  @default(false)\n  banReason String?\n  createdAt DateTime @default(now())\n\n  // Relations\n  ratings       Rating[]\n  Address       Address[]\n  stores        Store[]\n  buyerOrders   Order[]        @relation(\"BuyerRelation\")\n  notifications Notification[]\n  storeRatings  StoreRating[]\n}\n\nmodel Notification {\n  id        String   @id @default(cuid())\n  userId    String\n  title     String\n  message   String\n  type      String   @default(\"system\")\n  link      String?\n  read      Boolean  @default(false)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n}\n\nenum ProductOrigin {\n  LOCAL // ships domestically, ETA 7-10 days, COD available\n  ABROAD // ships internationally, ETA 20-25 days, no COD\n}\n\n// Required for creating a Product: name, description, mrp, price, images, category, storeId\nmodel Product {\n  id                    String        @id @default(cuid())\n  name                  String\n  description           String\n  mrp                   Float\n  price                 Float\n  images                String[]\n  category              String\n  inStock               Boolean       @default(true)\n  quantity              Int           @default(0)\n  sku                   String?\n  tags                  String[]      @default([])\n  scheduledAt           DateTime?\n  origin                ProductOrigin @default(LOCAL)\n  deliveryWithinState   Boolean       @default(true)\n  deliveryNationwide    Boolean       @default(true)\n  deliveryInternational Boolean       @default(false)\n  madeIn                String?\n  manufacturer          String?\n  material              String?\n  guaranteePeriod       String?\n  /// LOCAL only: seller may disable COD. Always false in DB for ABROAD (enforced in API).\n  acceptCod             Boolean       @default(true)\n  isDigital             Boolean       @default(false) // true = downloadable product\n  downloadUrl           String? // secure URL for digital file (set after order paid)\n  /// Wholesale/bulk pricing — store owner enables this; tiers define qty-based prices\n  isWholesale           Boolean       @default(false)\n  storeId               String\n  createdAt             DateTime      @default(now())\n  updatedAt             DateTime      @updatedAt\n\n  // Relations\n  store          Store                  @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  orderItems     OrderItem[]\n  rating         Rating[]\n  variantGroups  ProductVariantGroup[]\n  wholesaleTiers ProductWholesaleTier[]\n  adRequests     AdRequest[]\n}\n\n/**\n * ProductWholesaleTier — quantity-based price tiers set by the store owner.\n * Example: minQty=1  maxQty=9   price=10000\n * minQty=10 maxQty=99  price=8000\n * minQty=100 maxQty=null price=6000  (null = no upper limit)\n */\nmodel ProductWholesaleTier {\n  id        String @id @default(cuid())\n  productId String\n  minQty    Int // inclusive lower bound\n  maxQty    Int? // inclusive upper bound; null = no upper limit\n  price     Float // unit price for this tier\n  position  Int    @default(0) // display order (ascending minQty)\n\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@index([productId, minQty])\n}\n\n/**\n * ProductVariantGroup — defines one axis of variation for a product.\n * Examples:\n * { label: \"Color\",   type: \"IMAGE\",  required: true  }\n * { label: \"Storage\", type: \"TEXT\",   required: true  }\n * { label: \"Bundle\",  type: \"TEXT\",   required: false }\n * type: \"TEXT\" = text pill selector, \"IMAGE\" = thumbnail swatch selector\n */\nmodel ProductVariantGroup {\n  id        String           @id @default(cuid())\n  productId String\n  label     String // e.g. \"Color\", \"Storage\", \"Model\", \"Bundle\"\n  type      VariantGroupType @default(TEXT)\n  required  Boolean          @default(true)\n  position  Int              @default(0) // display order\n\n  product Product                @relation(fields: [productId], references: [id], onDelete: Cascade)\n  options ProductVariantOption[]\n\n  @@unique([productId, label])\n}\n\nenum VariantGroupType {\n  TEXT // shown as text pills / buttons\n  IMAGE // shown as image swatches with label\n}\n\n/**\n * ProductVariantOption — one selectable value within a group.\n * Examples for group \"Color\":\n * { label: \"Midnight Black\", image: \"https://...\", priceModifier: 0 }\n * Examples for group \"Storage\":\n * { label: \"128 GB\", priceModifier: 0 }\n * { label: \"256 GB\", priceModifier: 5000 }\n * { label: \"512 GB\", priceModifier: 15000 }\n * priceModifier: added to the base product price (can be negative for discounts).\n */\nmodel ProductVariantOption {\n  id            String  @id @default(cuid())\n  groupId       String\n  label         String // display text, e.g. \"Midnight Black\", \"256 GB\"\n  image         String? // only used when group type = IMAGE\n  sku           String? // optional per-option SKU\n  priceModifier Float   @default(0) // added to base price\n  quantity      Int     @default(0)\n  inStock       Boolean @default(true)\n  position      Int     @default(0) // display order\n\n  group ProductVariantGroup @relation(fields: [groupId], references: [id], onDelete: Cascade)\n\n  @@unique([groupId, label])\n}\n\nenum OrderStatus {\n  ORDER_PLACED\n  PROCESSING\n  SHIPPED\n  DELIVERED\n  CANCELLED\n}\n\nenum PaymentMethod {\n  COD\n  LEMONSQUEEZY\n  STRIPE\n  PAYSTACK\n  FLUTTERWAVE\n}\n\nenum PayoutStatus {\n  PENDING\n  PAID\n}\n\n// Required for creating an Order: total, userId, storeId, addressId, isPaid, paymentMethod, isCouponUsed, coupon (JSON), orderItems (nested)\nmodel Order {\n  id             String        @id @default(cuid())\n  total          Float\n  status         OrderStatus   @default(ORDER_PLACED)\n  userId         String\n  storeId        String\n  addressId      String\n  isPaid         Boolean       @default(false)\n  paymentMethod  PaymentMethod\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n  isCouponUsed   Boolean       @default(false)\n  coupon         Json          @default(\"{}\")\n  notes          String? // buyer special instructions\n  trackingNumber String? // shipping tracking number (auto-generated when marked SHIPPED)\n  orderItems     OrderItem[]\n  storeRating    StoreRating?\n\n  // Relations\n  user    User    @relation(\"BuyerRelation\", fields: [userId], references: [id])\n  store   Store   @relation(fields: [storeId], references: [id])\n  address Address @relation(fields: [addressId], references: [id])\n  refund  Refund?\n}\n\n// Required for creating an OrderItem: orderId, productId, quantity, price\nmodel OrderItem {\n  id                String @id @default(cuid())\n  orderId           String\n  productId         String\n  quantity          Int\n  price             Float\n  fulfilledQuantity Int    @default(0) // tracks partial fulfillment\n  variants          Json   @default(\"{}\") // selected variant options { groupLabel: optionLabel }\n\n  // Relations\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n\n  @@unique([orderId, productId])\n}\n\nenum RefundStatus {\n  REQUESTED\n  APPROVED\n  REJECTED\n  REFUNDED\n}\n\n// Refund / return requests\nmodel Refund {\n  id        String       @id @default(cuid())\n  orderId   String       @unique\n  reason    String\n  status    RefundStatus @default(REQUESTED)\n  adminNote String?\n  amount    Float? // approved refund amount (null until approved)\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  // Relations\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n}\n\n// Required for creating a Rating: rating, review, userId, productId\nmodel Rating {\n  id             String   @id @default(cuid())\n  rating         Int\n  review         String\n  reviewImages   String[] @default([]) // optional buyer-uploaded images\n  userId         String\n  productId      String\n  orderId        String\n  sellerResponse String?\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  // Relations\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, productId, orderId])\n}\n\n// Required for creating an Address: userId, name, email, street, city, state, zip, country, phone\nmodel Address {\n  id        String   @id @default(cuid())\n  userId    String\n  name      String\n  email     String\n  street    String\n  city      String\n  state     String\n  zip       String\n  country   String\n  phone     String\n  createdAt DateTime @default(now())\n\n  // Relations\n  Order Order[]\n  user  User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nenum DiscountType {\n  PERCENTAGE // e.g. 20% off\n  FIXED // e.g. ₦500 off\n}\n\n// Required for creating a Coupon: code, description, discount, forNewUser, isPublic, expiresAt\nmodel Coupon {\n  code          String       @id\n  description   String\n  discountType  DiscountType @default(PERCENTAGE)\n  discount      Float // percentage (0-100) or fixed amount depending on discountType\n  forNewUser    Boolean\n  forMember     Boolean      @default(false)\n  isPublic      Boolean\n  expiresAt     DateTime\n  maxUses       Int? // null = unlimited\n  usageCount    Int          @default(0)\n  minOrderValue Float? // null = no minimum\n  storeId       String? // null = platform-wide; set to restrict to one store\n  createdAt     DateTime     @default(now())\n\n  // Relations\n  store Store? @relation(fields: [storeId], references: [id], onDelete: Cascade)\n}\n\n// Required for creating a Store: userId, name, username, email, contact, logo, description, address (optional: , status, isActive)\nmodel Store {\n  id                    String   @id @default(cuid())\n  userId                String\n  name                  String\n  description           String\n  username              String   @unique\n  address               String   @default(\"\") // legacy plain-text (kept for backwards compat)\n  street                String? // structured address\n  city                  String?\n  state                 String?\n  zip                   String?\n  country               String   @default(\"Nigeria\")\n  deliveryStates        String[] @default([])\n  shippingLocalFee      Float    @default(7000)\n  shippingNationwideFee Float    @default(0)\n  shippingAbroadFee     Float    @default(15000)\n  shippingFreeAbove     Float    @default(0)\n  status                String   @default(\"pending\")\n  isActive              Boolean  @default(false)\n  logo                  String\n  banner                String?\n  email                 String\n  contact               String\n\n  // ─── Store Verification ──────────────────────────────────────────────────\n  verificationStatus         String  @default(\"unverified\") // unverified | pending | verified | rejected\n  verificationRejectedReason String? // reason for rejection if rejected\n\n  // ─── Verification & compliance (filled during verification step) ────────\n  cacNumber                  String? // CAC registration number\n  verificationDocumentType   String? // \"NIN\" | \"PASSPORT\"\n  verificationDocumentNumber String? // NIN number or passport number\n  verificationDocumentUrl    String? // image of document\n  facialVerificationUrl      String? // selfie image for facial verification\n\n  // ─── Payout details ─────────────────────────────────────────────────────\n  payoutBankName      String?\n  payoutAccountName   String?\n  payoutAccountNumber String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  Product      Product[]\n  Order        Order[]\n  storeRatings StoreRating[]\n  user         User          @relation(fields: [userId], references: [id])\n  Payout       Payout[]\n  Coupon       Coupon[]\n  adRequests   AdRequest[]\n}\n\nmodel StoreRating {\n  id        String   @id @default(cuid())\n  storeId   String\n  orderId   String   @unique\n  userId    String\n  rating    Int\n  review    String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  store Store @relation(fields: [storeId], references: [id], onDelete: Cascade)\n  order Order @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Payout tracking for sellers\nmodel Payout {\n  id        String       @id @default(cuid())\n  storeId   String\n  amount    Float\n  status    PayoutStatus @default(PENDING)\n  note      String?\n  createdAt DateTime     @default(now())\n  updatedAt DateTime     @updatedAt\n\n  // Relations\n  store Store @relation(fields: [storeId], references: [id], onDelete: Cascade)\n}\n\n/**\n * Platform-wide configuration — single row, key-value.\n * Keys in use:\n * commission_rate     Float  (e.g. 5.0 = 5%)\n * shipping_base_fee   Float  (flat fee for non-members, e.g. 7000)\n * shipping_abroad_fee Float  (abroad product shipping fee)\n * shipping_free_above Float  (order total above which shipping is free, e.g. 50000)\n * tax_rate            Float  (VAT/Tax percentage applied at checkout, e.g. 7.5 = 7.5%. 0 = disabled)\n */\nmodel PlatformConfig {\n  key       String   @id\n  value     String\n  updatedAt DateTime @updatedAt\n}\n\nenum AdRequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n// Ad requests from sellers to feature products on home page\nmodel AdRequest {\n  id          String          @id @default(cuid())\n  productId   String\n  storeId     String\n  status      AdRequestStatus @default(PENDING)\n  requestedAt DateTime        @default(now())\n  approvedAt  DateTime?\n  adminNote   String?\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  // Relations\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  store   Store   @relation(fields: [storeId], references: [id], onDelete: Cascade)\n}\n\nmodel MiddleBanner {\n  id          String    @id @default(cuid())\n  title       String\n  subtitle    String? // nullable\n  imageUrl    String\n  linkUrl     String? // nullable\n  ctaText     String? // nullable\n  position    Int       @default(0)\n  isActive    Boolean   @default(true)\n  countryCode String? // nullable\n  startsAt    DateTime? // nullable\n  endsAt      DateTime? // nullable\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n}\n"
}

